func (q *Queries) ListTestSessions(ctx context.Context, userID uuid.UUID) ([]*TestSession, error) {
	rows, err := q.db.Query(ctx, listTestSessions, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*TestSession{}
	for rows.Next() {
		var i TestSession
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.SurveyID,
			&i.Specialization,
			&i.TargetGrade,
			&i.Status,
			&i.Seed,
			&i.StartedAt,
			&i.FinishedAt,
			&i.ExpiresAt,
			&i.Theta,
			&i.Se,
			&i.ItemsCount,
			&i.CorrectCount,
			&i.Decision,
			&i.Percentile,
			&i.Flags,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

